  function validateLiveForm(kind){const read=id=>document.querySelector(`#m-${id}`)?.value.trim()||"",serialOk=value=>/^[A-Z0-9][A-Z0-9._/-]{2,63}$/.test(value.toUpperCase());if(["sale","activate","installation"].includes(kind)&&!serialOk(read("sn"))){toast("Перевірте серійний номер","Дозволено 3–64 латинські літери, цифри та . _ / -");return false}if(kind==="sale"&&(!read("date")||read("date")>localDateValue())){toast("Перевірте дату продажу","Дата не може бути порожньою або в майбутньому.");return false}if(kind==="activate"&&(!read("name")||read("phone").length<7||!/^\S+@\S+\.\S+$/.test(read("email"))||read("address").length<2)){toast("Заповніть дані покупця","Потрібні ПІБ, коректний телефон, email та адресу монтажу.");return false}if(kind==="installation"&&(!read("date")||read("date")>localDateValue()||!read("installer"))){toast("Перевірте дані монтажу","Потрібні монтажник і дата не пізніше сьогодні.");return false}if(["member","dealer"].includes(kind)&&read("email")&&!/^\S+@\S+\.\S+$/.test(read("email"))){toast("Перевірте email");return false}if(kind==="member"&&(!read("name")||!read("email")||read("password").length<8||read("password").length>72)){toast("Заповніть дані користувача","Потрібні ім’я, email і початковий пароль із 8–72 символів.");return false}if(kind==="member"&&read("role")==="Дилер"&&read("dealer")==="Не прив’язувати"){toast("Оберіть дилера","Користувач із роллю «Дилер» має бути прив’язаний до активного дилера.");return false}if(kind==="dealer"&&!read("name")){toast("Вкажіть назву дилера");return false}if(kind==="task"&&read("title").length<2){toast("Вкажіть назву завдання");return false}if(kind==="model"&&(!/^[A-Z0-9][A-Z0-9 ._/-]{1,63}$/.test(read("code").toUpperCase())||read("name").length<2||Number(read("months"))<1||Number(read("months"))>120)){toast("Перевірте модель","Код: 2–64 дозволені символи; назва: 2–160; гарантія: 1–120 місяців.");return false}return true}
  function showSaleSuccess(created){const context=liveContext(),token=created?.activation_token||"",url=window.WarrioBackend.activationUrl(context?.organization?.slug||"",created?.serial_number||"",token);title.textContent="Продаж зареєстровано";body.innerHTML=`<div style="display:grid;gap:14px"><div class="success-box"><b>${esc(created?.serial_number||"SN зареєстровано")}</b><span>Передайте покупцю це одноразове посилання. У базі збережено лише SHA-256 коду активації.</span></div><div class="form-group"><label>Безпечне посилання покупця</label><input id="sale-activation-url" readonly value="${esc(url)}"></div><small style="color:var(--muted)">Нове посилання можна перевипустити з картки продажу; попередній код після цього перестане діяти.</small></div>`;foot.innerHTML=`<button class="btn" id="sale-copy">Копіювати</button><a class="btn primary" href="${esc(url)}" target="_blank" rel="noopener">Відкрити активацію</a>`;overlay.classList.add("open");document.querySelector("#sale-copy").onclick=async()=>{try{await navigator.clipboard.writeText(url);toast("Посилання покупця скопійовано")}catch{document.querySelector("#sale-activation-url").select();toast("Виділіть і скопіюйте посилання")}}}
  async function deliverActivatedWarranty(created){const status=document.querySelector("#activation-delivery-status"),retry=document.querySelector("#activation-retry");if(!status||!created?.warranty_id||!created?.public_token)return;status.textContent="Створюємо приватний PDF із QR і надсилаємо через Resend…";retry.hidden=true;try{const sent=await window.WarrioData.sendWarrantyEmail({warrantyId:created.warranty_id,publicToken:created.public_token});status.textContent=sent.alreadySent?"PDF і email уже були доставлені.":"PDF із QR створено, збережено приватно й надіслано на email.";status.style.color="#0e8c5a";await refreshLiveData()}catch(error){status.textContent=`Гарантію активовано, але PDF/email не доставлено. ${businessMessage(error)}`;status.style.color="#c93653";retry.hidden=false}}
