  function csv(rows,name){const content=rows.map(r=>r.map(v=>`"${String(v).replaceAll('"','""')}"`).join(",")).join("\n");const a=document.createElement("a");a.href=URL.createObjectURL(new Blob(["\ufeff"+content],{type:"text/csv"}));a.download=name;a.click();URL.revokeObjectURL(a.href);toast("Файл підготовлено",name)}
  async function checkBackend(showToast=false){const status=document.querySelector("#backend-status");if(!window.WarrioBackend?.isConfigured()){status.innerHTML='<b><i class="online" style="background:#e94e68"></i> Supabase не налаштовано</b><span>Перевірте config.js</span>';if(showToast)toast("Supabase не налаштовано","Перевірте браузерну конфігурацію.");return false}status.innerHTML='<b><i class="online" style="background:#f2a112"></i> Перевіряємо Supabase</b><span>Безпечне з’єднання з API…</span>';try{const result=await window.WarrioBackend.health();if(!result.ok)throw new Error("Unexpected response");status.innerHTML=`<b><i class="online"></i> Supabase доступний</b><span>API відповів за ${result.latencyMs} мс</span>`;if(showToast)toast("Supabase працює",`Відповідь API: ${result.latencyMs} мс`);return true}catch(error){status.innerHTML='<b><i class="online" style="background:#e94e68"></i> Немає зв’язку з Supabase</b><span>Повторіть перевірку пізніше</span>';if(showToast)toast("Немає зв’язку з Supabase","Перевірте інтернет і стан проєкту.");return false}}
  async function finishActivation(){const sn=document.querySelector("#activation-sn").value.trim(),customer=document.querySelector("#activation-name").value.trim()||"Новий клієнт";if(!sn)return toast("Вкажіть серійний номер");if(isLive()){try{const context=liveContext();const result=await window.WarrioData.activateWarranty({organizationId:context.organization.id,serialNumber:sn,customerName:customer,customerPhone:document.querySelector("#activation-phone").value.trim(),customerEmail:document.querySelector("#activation-email").value.trim(),installationAddress:document.querySelector("#activation-address").value.trim()});const created=result?.[0];window.__lastPublicToken=created?.public_token||"";await refreshLiveData();showActivationSuccess(created)}catch(error){toast("Активацію не виконано",businessMessage(error))}return}const existing=warranties.find(x=>x.sn===sn);if(!existing)warranties.unshift({id:"WRR-2026-00197",sn,model:"NAVI 1000",customer,status:"Очікує монтажу",install:"Не призначено"});renderWarranties();toast("Гарантію активовано","Сертифікат WRR-2026-00197 створено.");setTimeout(()=>openModal("certificate",existing?.id||"WRR-2026-00197"),500)}
  function verifySale(){const sn=document.querySelector("#activation-sn").value.trim().toUpperCase();if(!sn)return toast("Вкажіть серійний номер");if(isLive()){const live=window.__warrioLiveData;const sale=live?.sales?.find(item=>item.product?.serial_number===sn);if(!sale)return toast("Продаж не знайдено","Спочатку дилер має зареєструвати цей SN.");if(live.warranties.some(item=>item.sale_id===sale.id))return toast("Гарантію вже активовано","Для цього продажу існує гарантія.");return toast("Продаж знайдено",`${sale.product?.model?.name||"Обладнання"} · ${sale.dealer_name_snapshot}`)}toast("Продаж знайдено","SN зареєстровано дилером Клімат Плюс.")}
